#!/usr/bin/env php
<?php

declare(strict_types=1);

/**
 * Lane-close agent session capture.
 *
 * While the Solo DB row for <solo-process-id> is alive, resolve provider/cwd/started_at
 * and extract that session's transcript via exact "Solo process ID: <id>" marker join
 * into staging .orbit/agent-sessions/<provider>/<lane-slug>/.
 *
 * Exact marker join: the marker text must select exactly one runtime-scoped provider
 * session candidate. Ambiguity or zero matches = loud failure with diagnostics.
 */

function main(array $argv): int
{
    // Robust arg parsing for mixed positional id + long options (works under test Process exec too)
    $rawArgv = $argv;
    $script = array_shift($rawArgv); // drop script name

    $soloProcessId = null;
    $options = [];

    foreach ($rawArgv as $a) {
        if (preg_match('/^--([a-z0-9-]+)(?:=(.*))?$/', $a, $m)) {
            $key = str_replace('-', '_', $m[1]);
            $val = $m[2] ?? true;
            $options[$key] = $val;
        } elseif ($soloProcessId === null && preg_match('/^\d+$/', $a)) {
            $soloProcessId = (int) $a;
        } elseif (preg_match('/^--solo-process-id=(.+)$/', $a, $m)) {
            $soloProcessId = (int) $m[1];
        }
    }

    if (array_key_exists('help', $options) || $soloProcessId === null) {
        fwrite(STDOUT, <<<'EOF'
    Usage:
      bin/orbit-agent-session-capture <solo-process-id> [--home=...] [--cwd=...] [--solo-db=...] [--orbit-dir=...] [--incarnation-started-at=<ISO8601>]

    Extracts the provider session for the given live Solo process id using exact marker match
    "Solo process ID: <id>" (and close variants). Writes staged capture under
    .orbit/agent-sessions/<provider>/<slug>/ containing manifest.json, usage.json,
    messages.jsonl, and raw/ copies.

    Exits non-zero with diagnostics on missing or ambiguous marker match.
    EOF);
        return $soloProcessId === null ? 2 : 0;
    }

    if ($soloProcessId <= 0) {
        fwrite(STDERR, "solo-process-id is required and must be positive\n");
        return 2;
    }

    $home = (string) ($options['home'] ?? getenv('HOME'));
    $cwd = realpath((string) ($options['cwd'] ?? getcwd())) ?: (string) ($options['cwd'] ?? getcwd());
    $soloDb = (string) ($options['solo_db'] ?? $options['solo-db'] ?? "{$home}/.config/soloterm/solo.db");
    $orbitDir = (string) ($options['orbit_dir'] ?? $options['orbit-dir'] ?? ($cwd.'/.orbit'));
    $explicitProvider = $options['provider'] ?? null;
    $explicitSlug = $options['slug'] ?? null;
    $incarnationFloor = null;
    $incarnationFloorTimestamp = null;

    if (array_key_exists('slug', $options)) {
        if (! is_string($explicitSlug) || $explicitSlug === '' || slugify($explicitSlug) !== $explicitSlug) {
            fwrite(STDERR, "invalid_explicit_slug\n");

            return 2;
        }
    }

    if (array_key_exists('incarnation_started_at', $options)) {
        $incarnationFloor = $options['incarnation_started_at'];

        if (! is_string($incarnationFloor) || ($incarnationFloorTimestamp = parseIso8601Timestamp($incarnationFloor)) === null) {
            fwrite(STDERR, "incarnation-started-at must be a valid ISO-8601 timestamp\n");
            return 2;
        }
    }

    if (! is_file($soloDb)) {
        fwrite(STDERR, "solo db not found: {$soloDb}\n");
        return 2;
    }

    $processRow = loadSoloProcessRow($soloDb, $soloProcessId);

    if ($processRow === null) {
        // Try spawned_processes as fallback for runtime liveness
        $processRow = loadSoloSpawnedProcess($soloDb, $soloProcessId);
    }

    if ($processRow === null) {
        fwrite(STDERR, "solo process {$soloProcessId} not found in solo db (row not alive)\n");
        return 2;
    }

    $kind = strtolower((string) ($processRow['kind'] ?? $processRow['process_kind'] ?? 'command'));
    $command = (string) ($processRow['command'] ?? '');
    $workingDir = realpath((string) ($processRow['working_dir'] ?? $processRow['project_path'] ?? $cwd)) ?: $cwd;
    $name = (string) ($processRow['name'] ?? $processRow['process_name'] ?? 'agent');

    $provider = $explicitProvider ?: inferProviderFromCommandOrName($command, $name, $kind);

    if ($incarnationFloor !== null && $provider !== 'codex') {
        fwrite(STDERR, "incarnation_floor_unsupported_provider\n");
        return 2;
    }

    // Resolve started_at from Solo row (prefer runtime spawned_at when the row is alive)
    $startedAt = $processRow['spawned_at']
        ?? $processRow['created_at']
        ?? $processRow['started_at']
        ?? null;

    fwrite(STDERR, sprintf(
        "resolved from solo.db: solo_process_id=%d provider=%s cwd=%s started_at=%s\n",
        $soloProcessId,
        $provider,
        $workingDir,
        $startedAt ?? 'null'
    ));

    $slug = is_string($explicitSlug) ? $explicitSlug : slugify($name ?: 'process-'.$soloProcessId).'-'.$soloProcessId;
    $providerRoot = rtrim($orbitDir, '/').'/agent-sessions/'.$provider;
    $stagingBase = $providerRoot.'/'.$slug;
    $temporaryStaging = uniqueStagingSiblingPath($providerRoot, $slug, 'tmp');
    $backupStaging = uniqueStagingSiblingPath($providerRoot, $slug, 'backup');
    ensureDirectory($providerRoot);
    ensureDirectory($temporaryStaging);

    $markerNeedle = "Solo process ID: {$soloProcessId}";

    $extract = match ($provider) {
        'codex' => captureCodexExact(
            $home,
            $workingDir,
            $soloProcessId,
            $startedAt,
            $incarnationFloor,
            $incarnationFloorTimestamp,
        ),
        'claude' => captureClaudeExact($home, $workingDir, $soloProcessId),
        'grok' => captureGrokExact($home, $workingDir, $soloProcessId),
        default => [
            'status' => 'unsupported',
            'reason' => $kind === 'terminal' ? 'terminal_kind_requires_waiver' : 'provider_unsupported',
            'checked' => [],
        ],
    };

    if (($extract['status'] ?? null) === 'ok') {
        // Write staged artifacts
        $manifest = [
            'schema_version' => 1,
            'provider' => $provider,
            'status' => 'ok',
            'slug' => $slug,
            'solo_process_id' => $soloProcessId,
            'kind' => $kind,
            'started_at' => $startedAt,
            'marker_match' => 'exact',
            'artifact' => $extract['artifact'] ?? null,
            'source' => $extract['source'] ?? 'lane_close_capture',
        ];

        if (isset($extract['disambiguation_basis'])) {
            $manifest['disambiguation_basis'] = $extract['disambiguation_basis'];
        }

        if (isset($extract['timestamp_corroboration'])) {
            $manifest['timestamp_corroboration'] = $extract['timestamp_corroboration'];
        }

        if (array_key_exists('incarnation_floor', $extract)) {
            $manifest['incarnation_floor'] = $extract['incarnation_floor'];
            $manifest['incarnation_floor_source'] = $extract['incarnation_floor_source'];
            $manifest['rollout_id'] = $extract['rollout_id'];
            $manifest['last_activity_at'] = $extract['last_activity_at'];
        }

        ensureDirectory($temporaryStaging.'/raw');
        writeJsonFile($temporaryStaging.'/manifest.json', $manifest);
        writeJsonFile($temporaryStaging.'/usage.json', $extract['usage'] ?? []);
        file_put_contents($temporaryStaging.'/messages.jsonl', ($extract['messages_jsonl'] ?? '')."\n");

        if (!empty($extract['raw_files'])) {
            foreach ($extract['raw_files'] as $rf) {
                $src = $rf['path'];
                $dest = $temporaryStaging.'/raw/'.$rf['archive_name'];
                if (is_file($src)) {
                    copyFileOrFail($src, $dest);
                }
            }
        }

    } else {
        // Failure or unsupported path: write explicit manifest entry (supports waiver later)
        $manifest = [
            'schema_version' => 1,
            'provider' => $provider,
            'status' => $extract['status'] ?? 'missing',
            'slug' => $slug,
            'solo_process_id' => $soloProcessId,
            'kind' => $kind,
            'started_at' => $startedAt,
            'reason' => $extract['reason'] ?? 'capture_failed',
            'checked' => $extract['checked'] ?? [],
            'marker' => $markerNeedle,
        ];

        if (($extract['status'] ?? null) === 'stale') {
            $manifest['incarnation_floor'] = $extract['incarnation_floor'];
            $manifest['incarnation_floor_source'] = $extract['incarnation_floor_source'];
            $manifest['rollout_id'] = $extract['rollout_id'];
            $manifest['last_activity_at'] = $extract['last_activity_at'];
        }

        writeJsonFile($temporaryStaging.'/manifest.json', $manifest);
    }

    try {
        replaceStagedCaptureDirectory($temporaryStaging, $stagingBase, $backupStaging);
    } catch (Throwable $throwable) {
        fwrite(STDERR, "capture staging replacement failed: {$throwable->getMessage()}\n");

        return 1;
    }

    if (($extract['status'] ?? null) === 'ok') {
        $result = [
            'status' => 'ok',
            'provider' => $provider,
            'solo_process_id' => $soloProcessId,
            'slug' => $slug,
            'started_at' => $startedAt,
            'staging_dir' => $stagingBase,
        ];
        echo json_encode($result, JSON_UNESCAPED_SLASHES)."\n";

        return 0;
    }

    fwrite(STDERR, "capture failed for solo_process_id={$soloProcessId} provider={$provider}: ".($extract['reason'] ?? 'unknown')."\n");
    if (($extract['status'] ?? null) === 'stale') {
        fwrite(STDERR, 'stale diagnostics: '.json_encode([
            'incarnation_floor' => $extract['incarnation_floor'],
            'incarnation_floor_source' => $extract['incarnation_floor_source'],
            'rollout_id' => $extract['rollout_id'],
            'last_activity_at' => $extract['last_activity_at'],
        ], JSON_UNESCAPED_SLASHES)."\n");
    }
    if (!empty($extract['checked'])) {
        fwrite(STDERR, "candidates checked:\n".json_encode($extract['checked'], JSON_PRETTY_PRINT)."\n");
    }
    if (($extract['status'] ?? '') === 'ambiguous') {
        fwrite(STDERR, "ambiguous: exact marker \"Solo process ID: {$soloProcessId}\" matched multiple sessions; inspect checked list above.\n");
    return 'codex';
}

function slugify(string $value): string
{
    $slug = strtolower((string) preg_replace('/[^a-zA-Z0-9]+/', '-', $value));
    $slug = trim($slug, '-');
    return $slug === '' ? 'session' : $slug;
}

function uniqueStagingSiblingPath(string $providerRoot, string $slug, string $kind): string
{
    do {
        $path = rtrim($providerRoot, '/')."/.{$slug}.{$kind}-".bin2hex(random_bytes(8));
    } while (file_exists($path) || is_link($path));

    return $path;
}

function assertDirectChildPath(string $path, string $providerRoot): void
{
    $normalizedRoot = rtrim($providerRoot, '/');

    if ($normalizedRoot === '') {
        $normalizedRoot = '/';
    }

    if (dirname($path) !== $normalizedRoot || in_array(basename($path), ['', '.', '..'], true)) {
        throw new RuntimeException("not_direct_child path={$path} provider_root={$normalizedRoot}");
    }
}

function replaceStagedCaptureDirectory(
    string $temp,
    string $final,
    string $backup,
    ?callable $rename = null,
): void {
    $providerRoot = dirname($final);
    assertDirectChildPath($temp, $providerRoot);
    assertDirectChildPath($final, $providerRoot);
    assertDirectChildPath($backup, $providerRoot);

    $rename ??= static fn (string $from, string $to): bool => @rename($from, $to);
    $hadFinal = file_exists($final) || is_link($final);

    if ($hadFinal) {
        assertDirectChildPath($final, $providerRoot);
        assertDirectChildPath($backup, $providerRoot);

        if (! $rename($final, $backup)) {
            throw new RuntimeException("final_to_backup_failed temp={$temp} final={$final} backup={$backup}");
        }
    }

    assertDirectChildPath($temp, $providerRoot);
    assertDirectChildPath($final, $providerRoot);

    if (! $rename($temp, $final)) {
        if (! $hadFinal) {
            throw new RuntimeException("temp_to_final_failed_no_backup temp={$temp} final={$final} backup={$backup}");
        }

        assertDirectChildPath($backup, $providerRoot);
        assertDirectChildPath($final, $providerRoot);

        if (! $rename($backup, $final)) {
            throw new RuntimeException("temp_to_final_and_rollback_failed temp={$temp} final={$final} backup={$backup}");
        }

        assertDirectChildPath($temp, $providerRoot);
        removePathRecursively($temp);

        throw new RuntimeException("temp_to_final_failed_rolled_back temp={$temp} final={$final} backup={$backup}");
    }

    if ($hadFinal) {
        assertDirectChildPath($backup, $providerRoot);
        removePathRecursively($backup);
    }
}

function removePathRecursively(string $path): void
{
    if (is_link($path) || is_file($path)) {
        if (! unlink($path)) {
            throw new RuntimeException("Unable to remove path: {$path}");
        }

        return;
    }

    if (! is_dir($path)) {
        return;
    }

    $iterator = new RecursiveIteratorIterator(
        new RecursiveDirectoryIterator($path, RecursiveDirectoryIterator::SKIP_DOTS),
        RecursiveIteratorIterator::CHILD_FIRST,
    );

    foreach ($iterator as $entry) {
        if ($entry->isLink() || $entry->isFile()) {
            if (! unlink($entry->getPathname())) {
                throw new RuntimeException("Unable to remove path: {$entry->getPathname()}");
            }

            continue;
        }

        if (! rmdir($entry->getPathname())) {
            throw new RuntimeException("Unable to remove directory: {$entry->getPathname()}");
        }
    }

    if (! rmdir($path)) {
        throw new RuntimeException("Unable to remove directory: {$path}");
    }
}

function ensureDirectory(string $directory): void
{
    if (is_dir($directory)) {
        return;
    }
    if (!mkdir($directory, 0o775, true) && !is_dir($directory)) {
        throw new RuntimeException("Unable to create directory: {$directory}");
    }
}

function writeJsonFile(string $path, array $payload): void
{
    ensureDirectory(dirname($path));
    file_put_contents($path, json_encode($payload, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR).PHP_EOL);
}

function copyFileOrFail(string $src, string $dest): void
{
    ensureDirectory(dirname($dest));
    if (!copy($src, $dest)) {
        throw new RuntimeException("copy failed: {$src} -> {$dest}");
    }
}

function fileContains(string $path, string $needle): bool
{
    if (!is_file($path)) {
        return false;
    }
    $fh = fopen($path, 'r');
    if ($fh === false) {
        return false;
    }
    while (!feof($fh)) {
        $chunk = fread($fh, 8192);
        if ($chunk !== false && str_contains($chunk, $needle)) {
            fclose($fh);
            return true;
        }
    }
    fclose($fh);
    return false;
}

/** @return list<string> */
function findFiles(string $root, string $glob): array
{
    $files = [];
    if (!is_dir($root)) {
        return $files;
    }
    $it = new RecursiveIteratorIterator(
        new RecursiveDirectoryIterator($root, RecursiveDirectoryIterator::SKIP_DOTS),
        RecursiveIteratorIterator::SELF_FIRST,
    );
    foreach ($it as $entry) {
        if ($entry->isFile() && fnmatch($glob, $entry->getFilename())) {
            $files[] = $entry->getPathname();
        }
    }
    return $files;
}

function captureCodexExact(
    string $home,
    string $cwd,
    int $soloProcessId,
    mixed $startedAt,
    ?string $incarnationFloor,
    ?DateTimeImmutable $incarnationFloorTimestamp,
): array
{
    $root = "{$home}/.codex/sessions";
    $candidates = [];
    $checked = [];
    $rollouts = findFiles($root, '*.jsonl');

    foreach ($rollouts as $file) {
        $checked[] = $file;
        if (! codexFileHasScopedMarker($file, $soloProcessId)) {
            continue;
        }
        $candidates[] = $file;
    }

    if ($candidates === []) {
        return [
            'status' => 'missing',
            'reason' => 'exact_marker_not_found',
            'checked' => array_slice($checked, 0, 20),
        ];
    }

    $normalizedCwd = normalizeCodexCwd($cwd);
    $fullOwners = [];
    $partialOwners = [];

    foreach ($candidates as $candidate) {
        $context = codexCandidateContext($candidate);

        if ($context['normalized_cwd'] !== $normalizedCwd) {
            continue;
        }

        $owner = [
            'path' => $candidate,
            'timestamp' => $context['timestamp'],
        ];

        if ($context['primary_solo_process_id'] === $soloProcessId) {
            $fullOwners[] = $owner;

            continue;
        }

        if ($context['primary_solo_process_id'] === null) {
            $partialOwners[] = $owner;
        }
    }

    if (count($fullOwners) > 1 || ($fullOwners === [] && count($partialOwners) > 1)) {
        return [
            'status' => 'ambiguous',
            'reason' => 'ambiguous_duplicate_markers',
            'checked' => array_slice($checked, 0, 20),
        ];
    }

    if ($fullOwners === [] && $partialOwners === []) {
        return [
            'status' => 'missing',
            'reason' => 'no_owned_marker_transcript',
            'checked' => array_slice($checked, 0, 20),
        ];
    }

    $ownership = $fullOwners !== [] ? 'full' : 'partial(no_primary_identity)';
    $chosenOwner = $fullOwners[0] ?? $partialOwners[0];
    $chosen = $chosenOwner['path'];
    $timestampCorroboration = codexTimestampCorroboration($chosenOwner['timestamp'], $startedAt);
    $disambiguationBasis = sprintf(
        'provider=codex; ownership=%s; normalized_cwd=exact; primary_solo_process_id=%s; timestamp_corroboration=%s',
        $ownership,
        $ownership === 'full' ? (string) $soloProcessId : 'none',
        $timestampCorroboration,
    );

    $incarnationActivity = null;

    if ($incarnationFloor !== null && $incarnationFloorTimestamp !== null) {
        $incarnationActivity = codexIncarnationActivity($chosen);

        if (
            $incarnationActivity['last_activity_timestamp'] === null
            || $incarnationActivity['last_activity_timestamp'] < $incarnationFloorTimestamp
        ) {
            return [
                'status' => 'stale',
                'reason' => 'stale_pre_restart_session',
                'checked' => array_slice($checked, 0, 20),
                'incarnation_floor' => $incarnationFloor,
                'incarnation_floor_source' => 'caller_attested',
                'rollout_id' => $incarnationActivity['rollout_id'],
                'last_activity_at' => $incarnationActivity['last_activity_at'],
            ];
        }
    }

    // Parse minimal usage + messages from the rollout (reuse light logic)
    $messages = [];
    $usage = ['input_tokens' => 0, 'output_tokens' => 0, 'total_tokens' => 0];
    foreach (jsonl($chosen) as $row) {
        $type = $row['type'] ?? '';
        if ($type === 'response_item' && isset($row['payload']['content'])) {
            foreach ($row['payload']['content'] as $c) {
                if (isset($c['text'])) {
                    $messages[] = ['role' => $row['payload']['role'] ?? 'unknown', 'content' => $c['text']];
                }
            }
        }
        if ($type === 'event_msg' && ($row['payload']['type'] ?? '') === 'token_count') {
            $u = $row['payload']['info']['total_token_usage'] ?? [];
            $usage['input_tokens'] = (int) ($u['input_tokens'] ?? 0);
            $usage['output_tokens'] = (int) ($u['output_tokens'] ?? 0);
            $usage['reasoning_tokens'] = (int) ($u['reasoning_output_tokens'] ?? 0);
            $usage['total_tokens'] = (int) ($u['total_tokens'] ?? 0);
        }
    }

    $messagesJsonl = implode("\n", array_map(fn($m) => json_encode(['role' => $m['role'], 'content' => $m['content']], JSON_UNESCAPED_SLASHES), $messages));

    $result = [
        'status' => 'ok',
        'source' => 'codex_exact_marker',
        'artifact' => $chosen,
        'usage' => $usage,
        'messages_jsonl' => $messagesJsonl,
        'raw_files' => [['path' => $chosen, 'archive_name' => basename($chosen)]],
    ];

    $result['disambiguation_basis'] = $disambiguationBasis;
    $result['timestamp_corroboration'] = $timestampCorroboration;

    if ($incarnationFloor !== null && $incarnationActivity !== null) {
        $result['incarnation_floor'] = $incarnationFloor;
        $result['incarnation_floor_source'] = 'caller_attested';
        $result['rollout_id'] = $incarnationActivity['rollout_id'];
        $result['last_activity_at'] = $incarnationActivity['last_activity_at'];
    }

    return $result;
}

/**
 * @return array{
 *     rollout_id: ?string,
 *     last_activity_at: ?string,
 *     last_activity_timestamp: ?DateTimeImmutable,
 * }
 */
function codexIncarnationActivity(string $path): array
});

